import{_ as a,o as e,c as t,a3 as _}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/bei-taoyan-de-yongqi/59-工作的本质是对他人的贡献.md","filePath":"books/bei-taoyan-de-yongqi/59-工作的本质是对他人的贡献.md","lastUpdated":1794748679000}'),o={name:"books/bei-taoyan-de-yongqi/59-工作的本质是对他人的贡献.md"};function n(r,p,s,i,d,c){return e(),t("div",null,[...p[0]||(p[0]=[_('<h2 id="工作的本质是对他人的贡献" tabindex="-1">工作的本质是对他人的贡献 <a class="header-anchor" href="#工作的本质是对他人的贡献" aria-label="Permalink to &quot;工作的本质是对他人的贡献&quot;">​</a></h2><p>青年：明白了。那么，假设我能够做到“自我接纳”，并且也能够做到“他者信赖”。那我会因此有什么样的变化呢？</p><p>哲人：首先，真诚地接受不能交换的“这个我”，这就是自我接纳。同时，对他人寄予无条件的信赖即他者信赖。</p><p>既能接纳自己又能信赖他人，这种情况下，对你来说的他人会是怎样的存在呢？</p><p>青年：……是伙伴吗？</p><p>哲人：正是如此。对他人寄予信赖也就是把他人看成伙伴。正因为是伙伴，所以才能够信赖。如果不是伙伴，也就做不到信赖。</p><p>并且，如果把他人看作伙伴，那你也就能够在所属的共同体中找到自己的位置，继而也就能够获得“可以在这里”的归属感。</p><p>青年：也就是说，要想获得归属感就必须把他人看作伙伴，而要做到视他人为伙伴就需要自我接纳和他者信赖。</p><p>哲人：是的，你理解得越来越快啦！并且，视他人为敌的人既做不到自我接纳，也无法充分做到他者信赖。</p><p>青年：好吧。人的确都在寻找一种“可以在这里”的归属感，因此就需要自我接纳和他者信赖。这一点我没有异议。</p><p>但是，仅凭把他人看作伙伴并给予信赖就可以获得归属感吗？</p><p>哲人：当然，共同体感觉并不是仅凭自我接纳和他者信赖就可以获得的。这里还需要第三个关键词——“他者贡献”。</p><p>青年：他者贡献？</p><p>哲人：对作为伙伴的他人给予影响、作出贡献，这就是他者贡献。</p><p>青年：贡献也就是发扬自我牺牲精神为周围人效劳吧？</p><p>哲人：他者贡献的意思并不是自我牺牲。相反，阿德勒把为他人牺牲自己人生的人称作“过度适应社会的人”，并对此给予警示。</p><p>并且，请你想一想。我们只有在感觉到自己的存在或行为对共同体有益的时候，也就是体会到“我对他人有用”的时候，才能切实感受到自己的价值。是这样吧？</p><p>也就是说，他者贡献并不是舍弃“我”而为他人效劳，它反而是为了能够体会到“我”的价值而采取的一种手段。</p><p>青年：贡献他人是为了自己？</p><p>哲人：是的，不需要自我牺牲。</p><p>青年：哎呀哎呀，您的论调越来越危险了吧？这可真是自掘坟墓啊！为了满足“我”而去为他人效劳，这不正是伪善的定义吗？！所以我才说您的主张全都是伪善！您的论调全都不可信！算了吧，先生！比起满口道德谎言的善人，我宁愿相信那些忠实于自己欲望的恶徒！</p><p>哲人：言之过早了。你还没有真正理解共同体感觉。</p><p>青年：那么，关于先生主张的他者贡献，请您举个具体例子吧。</p><p>哲人：最容易理解的他者贡献就是工作——到社会上去工作或者做家务。劳动并不是赚取金钱的手段，我们通过劳动来实现他者贡献、参与共同体、体会“我对他人有用”，进而获得自己的存在价值。</p><p>青年：您是说工作的本质是对他人的贡献？</p><p>哲人：当然，赚钱也是一个重大要素。正如你之前查到的陀思妥耶夫斯基所说的“被铸造的自由”一样。但是，有些富豪已经拥有了一生也花不完的巨额财产，但他们中的多数人至今依然继续忙碌工作着。为什么要工作呢？是因为无底的欲望吗？不是。这是为了他者贡献继而获得“可以在这里的”归属感。获得巨额财富之后便致力于参加慈善活动的富豪们，也为了能够体会自我价值、确认“可以在这里”的归属感而进行着各种各样的活动。</p><p>青年：嗯，这也许是一个真理。但是……</p><p>哲人：但是？</p><p>真诚接受不可交换的“这个我”的自我接纳；主张应该毫不怀疑人际关系基础，从而做到无条件的他者信赖。对于青年来说，这两条都还可以接受。但是，他对于他者贡献却不太明白。如果这种贡献是“为了他人”，那就势必会是充满痛苦的自我牺牲。另一方面，如果这种贡献是“为了自己”，那就是一种彻底的伪善。这一点必须得弄清楚。青年以坚定的口吻开始辩论。</p>',29)])])}const f=a(o,[["render",n]]);export{m as __pageData,f as default};
